content:
:root {
  --font-family: 'Helvetica Neue', Arial, 'Hiragino Kaku Gothic ProN', 'Hiragino Sans', Meiryo, sans-serif;
  --bg-color: #f1f5f9;
  --card-bg: #ffffff;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --primary-color: #2563eb;
  --primary-light: #eff6ff;
  --success-color: #10b981;
  --warning-color: #f59e0b;
  --danger-color: #ef4444;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* アプリ全体コンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ヘッダーエリア */
.header-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 0;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* KPIサマリーカード */
.summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.summary-card {
  background-color: var(--card-bg);
  border-radius: var(--radius-md);
  padding: 20px;
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: relative;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.summary-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.summary-card-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background-color: var(--primary-light);
  color: var(--primary-color);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  margin-bottom: 4px;
}

.summary-card-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
}

.summary-card-value {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.summary-card-sub {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* メインコンテンツカード */
.main-card {
  background-color: var(--card-bg);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-md);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-color);
}

.card-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 8px;
}

.card-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

/* 表示モード切替ボタングループ */
.view-toggle-group {
  display: inline-flex;
  background-color: #f8fafc;
  padding: 4px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  gap: 4px;
}

.toggle-btn {
  background: transparent;
  border: none;
  padding: 6px 14px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.toggle-btn:hover {
  color: var(--text-main);
}

.toggle-btn-active {
  background-color: #ffffff;
  color: var(--primary-color);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

/* グラフ表示コンテナ */
.chart-container {
  width: 100%;
  height: 380px;
  min-height: 340px;
  position: relative;
}

/* recharts用カスタムツールチップ */
.custom-tooltip {
  background-color: rgba(15, 23, 42, 0.94);
  color: #ffffff;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-size: 0.85rem;
  min-width: 160px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(4px);
}

.tooltip-month {
  font-weight: 700;
  font-size: 0.95rem;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  color: #f8fafc;
}

.tooltip-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 4px;
}

.tooltip-row:last-child {
  margin-bottom: 0;
}

.tooltip-label {
  color: #cbd5e1;
  display: flex;
  align-items: center;
  gap: 6px;
}

.tooltip-value {
  font-weight: 600;
  font-family: monospace, sans-serif;
  color: #ffffff;
}

/* データ編集セクション */
.editor-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.editor-table-wrapper {
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: #ffffff;
  -webkit-overflow-scrolling: touch;
}

.editor-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.9rem;
  min-width: 680px;
}

.editor-th {
  background-color: #f8fafc;
  color: var(--text-muted);
  font-weight: 600;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
  white-space: nowrap;
}

.editor-th:nth-child(n+2) {
  text-align: right;
}

.editor-td {
  padding: 10px 16px;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-main);
  vertical-align: middle;
}

.editor-td:nth-child(n+2) {
  text-align: right;
}

.editor-table tr:last-child .editor-td {
  border-bottom: none;
}

.editor-table tr:hover .editor-td {
  background-color: #f8fafc;
}

/* 入力フォーム */
.editor-input {
  width: 100%;
  max-width: 160px;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  color: var(--text-main);
  background-color: #ffffff;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.editor-input:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

/* リセットボタン */
.reset-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 8px 16px;
  font-size: 0.85rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
}

.reset-btn:hover {
  background-color: #f8fafc;
  color: var(--danger-color);
  border-color: #fca5a5;
}

.reset-btn:active {
  background-color: #fef2f2;
}

/* レスポンシブ対応 */
@media (max-width: 768px) {
  .app-container {
    padding: 16px 12px 36px;
    gap: 16px;
  }

  .header-title {
    font-size: 1.4rem;
  }

  .card-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .card-controls {
    width: 100%;
    justify-content: space-between;
  }

  .view-toggle-group {
    width: 100%;
    display: flex;
  }

  .toggle-btn {
    flex: 1;
    text-align: center;
    padding: 8px 4px;
    font-size: 0.75rem;
  }

  .chart-container {
    height: 300px;
  }

  .main-card {
    padding: 16px;
  }
}

@media (max-width: 480px) {
  .summary-grid {
    grid-template-columns: 1fr;
  }
}

export type ViewMode = 'current' | 'comparison' | 'target';

export type SalesField = 'sales' | 'target' | 'previousYear';

export interface MonthlySalesRecord {
  month: string;
  sales: number;
  target: number;
  previousYear: number;
}

export interface SummaryMetrics {
  totalSales: number;
  averageSales: number;
  highestMonth: string;
  highestSales: number;
  lowestMonth?: string;
  lowestSales?: number;
  targetAchieveRate: number;
}

export interface SalesUpdatePayload {
  index: number;
  field: SalesField;
  value: number;
}

import { SummaryMetrics } from '../types';

interface SummaryCardsProps {
  metrics: SummaryMetrics;
}

export default function SummaryCards({ metrics }: SummaryCardsProps) {
  const formattedTotal = (metrics.totalSales / 10000).toLocaleString(undefined, {
    maximumFractionDigits: 1,
  });

  const formattedAverage = (metrics.averageSales / 10000).toLocaleString(undefined, {
    maximumFractionDigits: 1,
  });

  const formattedHighest = (metrics.highestSales / 10000).toLocaleString(undefined, {
    maximumFractionDigits: 1,
  });

  const formattedLowest = ((metrics.lowestSales ?? 0) / 10000).toLocaleString(undefined, {
    maximumFractionDigits: 1,
  });

  const rawRate = metrics.targetAchieveRate;
  const isRateValid = typeof rawRate === 'number' && Number.isFinite(rawRate);
  const formattedAchieveRate = isRateValid ? rawRate.toFixed(1) : '0.0';

  const achieveColor = !isRateValid
    ? 'var(--text-main)'
    : rawRate >= 100
    ? 'var(--success-color, #10b981)'
    : rawRate >= 80
    ? 'var(--warning-color, #f59e0b)'
    : 'var(--danger-color)';

  return (
    <div className="summary-grid">
      <div className="summary-card">
        <div className="summary-card-icon">¥</div>
        <div className="summary-card-label">年間総売上</div>
        <div className="summary-card-value">{formattedTotal}万円</div>
        <div className="summary-card-sub">12ヶ月間の累計実績</div>
      </div>

      <div className="summary-card">
        <div className="summary-card-icon">📈</div>
        <div className="summary-card-label">月平均売上</div>
        <div className="summary-card-value">{formattedAverage}万円</div>
        <div className="summary-card-sub">月間ペース</div>
      </div>

      <div className="summary-card">
        <div className="summary-card-icon">🏆</div>
        <div className="summary-card-label">最高売上月</div>
        <div className="summary-card-value">{metrics.highestMonth}</div>
        <div className="summary-card-sub">実績: {formattedHighest}万円</div>
      </div>

      <div className="summary-card">
        <div className="summary-card-icon">📉</div>
        <div className="summary-card-label">最低売上月</div>
        <div className="summary-card-value">{metrics.lowestMonth ?? '-'}</div>
        <div className="summary-card-sub">実績: {formattedLowest}万円</div>
      </div>

      <div className="summary-card">
        <div className="summary-card-icon">🎯</div>
        <div className="summary-card-label">年間目標達成率</div>
        <div className="summary-card-value" style={{ color: achieveColor }}>
          {formattedAchieveRate}%
        </div>
        <div className="summary-card-sub">年間目標対比</div>
      </div>
    </div>
  );
}

import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { MonthlySalesRecord, ViewMode } from '../types';

const CHART_COLORS = {
  currentSales: '#2563eb',
  previousYear: '#94a3b8',
  target: '#10b981',
  axis: '#64748b',
  grid: '#e2e8f0',
  legendText: '#0f172a',
} as const;

interface SalesChartProps {
  data: MonthlySalesRecord[];
  viewMode: ViewMode;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
    dataKey?: string | number;
    payload?: MonthlySalesRecord;
  }>;
  label?: string;
}

function CustomTooltipContent({ active, payload, label }: CustomTooltipProps) {
  if (!active || !payload || payload.length === 0) {
    return null;
  }

  const record = payload[0]?.payload;
  const currentSales = record?.sales ?? 0;
  const targetSales = record?.target ?? 0;
  const prevSales = record?.previousYear ?? 0;

  const targetDiff = currentSales - targetSales;
  const prevDiff = currentSales - prevSales;
  const targetRate = targetSales > 0 ? ((currentSales / targetSales) * 100).toFixed(1) : null;
  const prevRate = prevSales > 0 ? ((currentSales / prevSales) * 100).toFixed(1) : null;

  return (
    <div className="custom-tooltip">
      <div className="tooltip-month">{label}</div>
      {payload.map((item, index) => (
        <div key={index} className="tooltip-row">
          <span className="tooltip-label" style={{ color: item.color }}>
            ● {item.name}:
          </span>
          <span className="tooltip-value">
            {(item.value / 10000).toLocaleString()}万円
          </span>
        </div>
      ))}

      {record && (
        <div style={{ marginTop: '8px', paddingTop: '6px', borderTop: '1px solid rgba(255, 255, 255, 0.15)' }}>
          {targetRate !== null && (
            <div className="tooltip-row">
              <span className="tooltip-label">目標差:</span>
              <span
                className="tooltip-value"
                style={{ color: targetDiff >= 0 ? '#34d399' : '#f87171' }}
              >
                {targetDiff >= 0 ? '+' : ''}{(targetDiff / 10000).toFixed(1)}万円 ({targetRate}%)
              </span>
            </div>
          )}
          {prevRate !== null && (
            <div className="tooltip-row">
              <span className="tooltip-label">前年差:</span>
              <span
                className="tooltip-value"
                style={{ color: prevDiff >= 0 ? '#34d399' : '#f87171' }}
              >
                {prevDiff >= 0 ? '+' : ''}{(prevDiff / 10000).toFixed(1)}万円 ({prevRate}%)
              </span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default function SalesChart({ data = [], viewMode }: SalesChartProps) {
  const formatYAxis = (value: number) => {
    return `${value / 10000}万`;
  };

  return (
    <div className="chart-container">
      <ResponsiveContainer width="100%" height="100%">
        <ComposedChart
          data={data}
          margin={{ top: 16, right: 16, left: 0, bottom: 8 }}
        >
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={CHART_COLORS.grid} />
          <XAxis
            dataKey="month"
            stroke={CHART_COLORS.axis}
            tick={{ fill: CHART_COLORS.axis, fontSize: 12 }}
            tickLine={false}
          />
          <YAxis
            stroke={CHART_COLORS.axis}
            tick={{ fill: CHART_COLORS.axis, fontSize: 12 }}
            tickLine={false}
            tickFormatter={formatYAxis}
          />
          <Tooltip content={<CustomTooltipContent />} />
          <Legend
            wrapperStyle={{ paddingTop: '12px' }}
            formatter={(value: string) => (
              <span style={{ color: CHART_COLORS.legendText, fontSize: '0.85rem' }}>{value}</span>
            )}
          />

          {viewMode === 'comparison' && (
            <Bar
              dataKey="previousYear"
              name="前年実績"
              fill={CHART_COLORS.previousYear}
              radius={[4, 4, 0, 0]}
              maxBarSize={36}
            />
          )}

          <Bar
            dataKey="sales"
            name="当年売上"
            fill={CHART_COLORS.currentSales}
            radius={[4, 4, 0, 0]}
            maxBarSize={36}
          />

          {viewMode === 'target' && (
            <Line
              type="monotone"
              dataKey="target"
              name="売上目標"
              stroke={CHART_COLORS.target}
              strokeWidth={3}
              strokeDasharray="5 5"
              dot={{ r: 4, fill: CHART_COLORS.target }}
              activeDot={{ r: 6 }}
            />
          )}
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  );
}

import { useState, useMemo, ChangeEvent } from 'react';
import { MonthlySalesRecord, SummaryMetrics, ViewMode } from './types';
import SummaryCards from './components/SummaryCards';
import SalesChart from './components/SalesChart';

const INITIAL_DATA: MonthlySalesRecord[] = [
  { month: '1月', sales: 4200000, target: 4500000, previousYear: 3900000 },
  { month: '2月', sales: 3800000, target: 4000000, previousYear: 3600000 },
  { month: '3月', sales: 5600000, target: 5200000, previousYear: 5100000 },
  { month: '4月', sales: 4900000, target: 4800000, previousYear: 4400000 },
  { month: '5月', sales: 4700000, target: 4600000, previousYear: 4500000 },
  { month: '6月', sales: 5300000, target: 5000000, previousYear: 4800000 },
  { month: '7月', sales: 6100000, target: 5800000, previousYear: 5700000 },
  { month: '8月', sales: 5800000, target: 5500000, previousYear: 5400000 },
  { month: '9月', sales: 5100000, target: 5200000, previousYear: 4900000 },
  { month: '10月', sales: 5400000, target: 5300000, previousYear: 5000000 },
  { month: '11月', sales: 6300000, target: 6000000, previousYear: 5800000 },
  { month: '12月', sales: 7200000, target: 6800000, previousYear: 6700000 },
];

export default function App() {
  const [salesData, setSalesData] = useState<MonthlySalesRecord[]>(INITIAL_DATA);
  const [inputValues, setInputValues] = useState<string[]>(() =>
    INITIAL_DATA.map((d) => String(d.sales))
  );
  const [viewMode, setViewMode] = useState<ViewMode>('current');

  const metrics: SummaryMetrics = useMemo(() => {
    let totalSales = 0;
    let totalTarget = 0;
    let highestMonth = salesData[0]?.month || '1月';
    let highestSales = salesData[0]?.sales || 0;
    let lowestMonth = salesData[0]?.month || '1月';
    let lowestSales = salesData[0]?.sales || 0;

    salesData.forEach((record) => {
      totalSales += record.sales;
      totalTarget += record.target;

      if (record.sales > highestSales) {
        highestSales = record.sales;
        highestMonth = record.month;
      }
      if (record.sales < lowestSales) {
        lowestSales = record.sales;
        lowestMonth = record.month;
      }
    });

    const count = salesData.length || 1;
    const averageSales = totalSales / count;
    const targetAchieveRate = totalTarget > 0 ? (totalSales / totalTarget) * 100 : 0;

    return {
      totalSales,
      averageSales,
      highestMonth,
      highestSales,
      lowestMonth,
      lowestSales,
      targetAchieveRate,
    };
  }, [salesData]);

  const handleSalesChange = (index: number, e: ChangeEvent<HTMLInputElement>) => {
    const rawVal = e.target.value.replace(/[^0-9]/g, '');

    setInputValues((prev) => {
      const next = [...prev];
      next[index] = rawVal;
      return next;
    });

    const numVal = rawVal === '' ? 0 : Number(rawVal);
    setSalesData((prev) => {
      const next = [...prev];
      next[index] = { ...next[index], sales: numVal };
      return next;
    });
  };

  const handleSalesBlur = (index: number) => {
    if (inputValues[index] === '') {
      setInputValues((prev) => {
        const next = [...prev];
        next[index] = '0';
        return next;
      });
    }
  };

  const handleReset = () => {
    setSalesData(INITIAL_DATA);
    setInputValues(INITIAL_DATA.map((d) => String(d.sales)));
  };

  return (
    <div className="app-container">
      <header className="header-section">
        <h1 className="header-title">年間売上推移ダッシュボード</h1>
        <p className="header-subtitle">
          1月〜12月の売上実績・前年比較・目標達成状況の確認および売上シミュレーション
        </p>
      </header>

      <SummaryCards metrics={metrics} />

      <main className="main-card">
        <div className="card-header">
          <h2 className="card-title">月別売上推移</h2>
          <div className="card-controls">
            <div className="view-toggle-group">
              <button
                type="button"
                className={viewMode === 'current' ? 'toggle-btn toggle-btn-active' : 'toggle-btn'}
                onClick={() => setViewMode('current')}
              >
                当年売上のみ
              </button>
              <button
                type="button"
                className={viewMode === 'comparison' ? 'toggle-btn toggle-btn-active' : 'toggle-btn'}
                onClick={() => setViewMode('comparison')}
              >
                前年比較
              </button>
              <button
                type="button"
                className={viewMode === 'target' ? 'toggle-btn toggle-btn-active' : 'toggle-btn'}
                onClick={() => setViewMode('target')}
              >
                目標対比
              </button>
            </div>
          </div>
        </div>

        <SalesChart data={salesData} viewMode={viewMode} />
      </main>

      <section className="main-card">
        <div className="card-header">
          <h2 className="card-title">月別売上データ編集</h2>
          <div className="card-controls">
            <button type="button" className="reset-btn" onClick={handleReset}>
              初期値に戻す
            </button>
          </div>
        </div>

        <div className="editor-section">
          <div className="editor-table-wrapper">
            <table className="editor-table">
              <thead>
                <tr>
                  <th className="editor-th">月</th>
                  <th className="editor-th">当年売上実績 (円)</th>
                  <th className="editor-th">売上目標 (円)</th>
                  <th className="editor-th">前年実績 (円)</th>
                  <th className="editor-th">目標達成率</th>
                </tr>
              </thead>
              <tbody>
                {salesData.map((record, index) => {
                  const rate =
                    record.target > 0
                      ? ((record.sales / record.target) * 100).toFixed(1)
                      : '0.0';
                  const isModified = record.sales !== INITIAL_DATA[index].sales;

                  return (
                    <tr
                      key={record.month}
                      style={{
                        backgroundColor: isModified ? 'var(--primary-light)' : undefined,
                      }}
                    >
                      <td className="editor-td" style={{ fontWeight: 600 }}>
                        <div style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}>
                          <span>{record.month}</span>
                          {isModified && (
                            <span
                              style={{
                                fontSize: '0.75rem',
                                color: 'var(--primary-color)',
                                backgroundColor: '#ffffff',
                                border: '1px solid var(--border-color)',
                                borderRadius: 'var(--radius-sm)',
                                padding: '1px 6px',
                                fontWeight: 500,
                              }}
                            >
                              変更あり
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="editor-td">
                        <input
                          type="text"
                          inputMode="numeric"
                          className="editor-input"
                          value={inputValues[index]}
                          onChange={(e) => handleSalesChange(index, e)}
                          onBlur={() => handleSalesBlur(index)}
                          onFocus={(e) => e.target.select()}
                          aria-label={`${record.month}の売上実績`}
                        />
                      </td>
                      <td className="editor-td">
                        {record.target.toLocaleString()} 円
                      </td>
                      <td className="editor-td">
                        {record.previousYear.toLocaleString()} 円
                      </td>
                      <td
                        className="editor-td"
                        style={{
                          fontWeight: 600,
                          color: record.sales >= record.target ? '#10b981' : '#f59e0b',
                        }}
                      >
                        {rate}%
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </section>
    </div>
  );
}
